-- Freely licensed catalogue photos stored in Storage under media/catalog/<slug>/. Re-runnable.
delete from public.strain_photos;
-- list thumbnails: first flower photo, else first plant photo
update public.strains s set image_url = p.thumb_url, image_credit = p.author || ' · ' || p.license
  from (select distinct on (strain_id) strain_id, thumb_url, author, license from public.strain_photos order by strain_id, (kind <> 'bud'), sort) p
  where p.strain_id = s.id;
update public.strains s set image_url = null, image_credit = null where slug in ('white-dwarf') and not exists (select 1 from public.strain_photos p where p.strain_id = s.id);
